const cfg = flow.get("stormConfig") || {};
const capUrl = cfg.capFeedUrl || "https://alerts.metservice.com/cap/rss";
msg.method = "GET";
msg.url = `${capUrl}${capUrl.includes("?") ? "&" : "?"}_ts=${Date.now()}`;
msg.headers = {
    "User-Agent": "victron-storm-watch/1.0"
};
return msg;

const CONFIG = {
    // CAP feed to poll
    capFeedUrl: "https://alerts.metservice.com/cap/rss",

    // Optional fixed portal ID fallback if topic discovery has not happened yet.
    // Example: "ABCD1234EF56". Leave empty to auto-discover from N/<portalId>/... topics.
    portalId: "",

    // Home location fallback (used when GPS topics are unavailable)
    home: {
        lat: null,
        lon: null,
        name: "Home"
    },

    // If true, prefer live Victron GPS values when available.
    useVictronGps: true,

    // If CAP item has no geometry, optionally match this against area text.
    // Example: ["Auckland", "Northland"]
    homeAreaKeywords: [],

    // If true, alerts without geometry/area matching are treated as in-zone.
    matchAllWithoutGeometry: false,

    // Include future alerts this many minutes before onset/effective time.
    leadMinutes: 30,

    // Keep protection active this long after last alert expiry.
    clearHoldMinutes: 60,

    // Minimum SOC values to enforce when inactive/active.
    normalMinSoc: 20,
    stormMinSoc: 80,

    // CAP severity filter. Leave empty to accept any severity.
    acceptedSeverities: ["Moderate", "Severe", "Extreme"],

    // Storm-ish keywords looked up in event/title/description.
    stormKeywords: [
        "storm",
        "thunderstorm",
        "severe weather",
        "heavy rain",
        "flood",
        "wind",
        "gale",
        "squall",
        "cyclone",
        "tornado",
        "hail",
        "snow",
        "ice"
    ]
};

flow.set("stormConfig", CONFIG);

function asArray(v) {
    if (v === undefined || v === null) return [];
    return Array.isArray(v) ? v : [v];
}

function firstText(v) {
    if (Array.isArray(v)) {
        for (const item of v) {
            const t = firstText(item);
            if (t) return t;
        }
        return "";
    }
    if (typeof v === "object" && v !== null) {
        if (v._ !== undefined) return String(v._).trim();
        return "";
    }
    return String(v).trim();
}

function num(v) {
    const n = Number(v);
    return Number.isFinite(n) ? n : null;
}

function parseDateMs(v) {
    const t = firstText(v);
    if (!t) return null;
    const ms = Date.parse(t);
    return Number.isFinite(ms) ? ms : null;
}

function normalize(s) {
    return firstText(s).toLowerCase();
}

function clampSocStep5(v, fallback) {
    const n = num(v);
    const base = Number.isFinite(n) ? n : fallback;
    const clipped = Math.max(0, Math.min(100, base));
    return Math.round(clipped / 5) * 5;
}

function parsePolygon(polyText) {
    const t = firstText(polyText);
    if (!t) return [];
    const pairs = t.trim().split(/\s+/);
    const points = [];
    for (const pair of pairs) {
        const parts = pair.split(",");
        if (parts.length !== 2) continue;
        const lat = num(parts[0]);
        const lon = num(parts[1]);
        if (lat === null || lon === null) continue;
        points.push([lat, lon]);
    }
    return points;
}

function pointInPolygon(lat, lon, points) {
    // Ray casting in lon/lat plane.
    let inside = false;
    const x = lon;
    const y = lat;
    for (let i = 0, j = points.length - 1; i < points.length; j = i++) {
        const yi = points[i][0];
        const xi = points[i][1];
        const yj = points[j][0];
        const xj = points[j][1];

        const intersects = ((yi > y) !== (yj > y)) &&
            (x < ((xj - xi) * (y - yi)) / ((yj - yi) || 1e-12) + xi);
        if (intersects) inside = !inside;
    }
    return inside;
}

function parseCircle(circleText) {
    // CAP circle format: "lat,lon radiusKm"
    const t = firstText(circleText);
    if (!t) return null;
    const parts = t.trim().split(/\s+/);
    if (parts.length < 2) return null;
    const center = parts[0].split(",");
    if (center.length !== 2) return null;
    const lat = num(center[0]);
    const lon = num(center[1]);
    const radiusKm = num(parts[1]);
    if (lat === null || lon === null || radiusKm === null || radiusKm < 0) return null;
    return { lat, lon, radiusKm };
}

function haversineKm(lat1, lon1, lat2, lon2) {
    const toRad = (d) => d * Math.PI / 180;
    const R = 6371;
    const dLat = toRad(lat2 - lat1);
    const dLon = toRad(lon2 - lon1);
    const a = Math.sin(dLat / 2) ** 2 +
        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
    return 2 * R * Math.asin(Math.sqrt(a));
}

const gpsLat = num(flow.get("gpsLatitude"));
const gpsLon = num(flow.get("gpsLongitude"));
const cfgLat = num(CONFIG.home.lat);
const cfgLon = num(CONFIG.home.lon);

let homeLat = cfgLat;
let homeLon = cfgLon;
let homeSource = "config";

if (CONFIG.useVictronGps && gpsLat !== null && gpsLon !== null) {
    homeLat = gpsLat;
    homeLon = gpsLon;
    homeSource = "victron-gps";
}

const hasHome = (homeLat !== null && homeLon !== null);
const acceptedSeverity = new Set(asArray(CONFIG.acceptedSeverities).map((s) => firstText(s).toLowerCase()).filter(Boolean));
const stormKeywords = asArray(CONFIG.stormKeywords).map((k) => firstText(k).toLowerCase()).filter(Boolean);
const areaKeywords = asArray(CONFIG.homeAreaKeywords).map((k) => firstText(k).toLowerCase()).filter(Boolean);

const now = Date.now();
const leadMs = Math.max(0, (num(CONFIG.leadMinutes) || 0) * 60000);
const holdMs = Math.max(0, (num(CONFIG.clearHoldMinutes) || 0) * 60000);

const p = msg.payload || {};
let items = [];

if (p.rss && p.rss.channel) {
    const channel = asArray(p.rss.channel)[0] || {};
    items = asArray(channel.item);
} else if (p.feed && p.feed.entry) {
    // Some feeds may be Atom instead of RSS.
    items = asArray(p.feed.entry);
}

const matched = [];

for (const item of items) {
    const title = firstText(item.title);
    const event = firstText(item["cap:event"]) || title;
    const desc = firstText(item.description) || firstText(item.summary) || "";
    const severity = firstText(item["cap:severity"]);
    const areaDesc = firstText(item["cap:areaDesc"]) || firstText(item["cap:area"]);

    const searchable = `${event} ${title} ${desc}`.toLowerCase();
    const hasStormKeyword = stormKeywords.length === 0 || stormKeywords.some((k) => searchable.includes(k));
    if (!hasStormKeyword) continue;

    if (acceptedSeverity.size > 0) {
        const sevNorm = severity.toLowerCase();
        if (!acceptedSeverity.has(sevNorm)) continue;
    }

    const onsetMs = parseDateMs(item["cap:onset"]) || parseDateMs(item["cap:effective"]);
    const effectiveMs = parseDateMs(item["cap:effective"]);
    const expiresMs = parseDateMs(item["cap:expires"]) || parseDateMs(item.pubDate);

    const startsMs = onsetMs || effectiveMs || now;
    if (startsMs - leadMs > now) continue;
    if (expiresMs !== null && expiresMs < now) continue;

    let inZone = false;
    let zoneType = "none";

    if (hasHome) {
        const polygons = asArray(item["cap:polygon"]);
        for (const poly of polygons) {
            const pts = parsePolygon(poly);
            if (pts.length >= 3 && pointInPolygon(homeLat, homeLon, pts)) {
                inZone = true;
                zoneType = "polygon";
                break;
            }
        }

        if (!inZone) {
            const circles = asArray(item["cap:circle"]);
            for (const c of circles) {
                const circle = parseCircle(c);
                if (!circle) continue;
                const dKm = haversineKm(homeLat, homeLon, circle.lat, circle.lon);
                if (dKm <= circle.radiusKm) {
                    inZone = true;
                    zoneType = "circle";
                    break;
                }
            }
        }
    }

    if (!inZone && areaKeywords.length > 0) {
        const areaNorm = areaDesc.toLowerCase();
        inZone = areaKeywords.some((k) => areaNorm.includes(k));
        if (inZone) zoneType = "area-keyword";
    }

    if (!inZone && CONFIG.matchAllWithoutGeometry && !firstText(item["cap:polygon"]) && !firstText(item["cap:circle"])) {
        inZone = true;
        zoneType = "no-geometry-fallback";
    }

    if (!inZone) continue;

    matched.push({
        title,
        event,
        severity: severity || "Unknown",
        area: areaDesc,
        zoneType,
        startsAt: startsMs ? new Date(startsMs).toISOString() : null,
        expiresAt: expiresMs ? new Date(expiresMs).toISOString() : null,
        expiresTs: expiresMs
    });
}

let holdUntil = num(flow.get("stormHoldUntil")) || 0;
let shouldProtect = matched.length > 0;
let reason = shouldProtect ? "active-alert" : "clear";

if (shouldProtect) {
    let furthestExpiry = 0;
    for (const m of matched) {
        if (m.expiresTs && m.expiresTs > furthestExpiry) {
            furthestExpiry = m.expiresTs;
        }
    }
    holdUntil = (furthestExpiry || now) + holdMs;
    flow.set("stormHoldUntil", holdUntil);
} else if (holdUntil > now) {
    shouldProtect = true;
    reason = "hold-timer";
} else {
    flow.set("stormHoldUntil", 0);
}

const discoveredPortalId = flow.get("portalId") || "";
const portalId = CONFIG.portalId || discoveredPortalId;

msg.stormWatch = {
    timestamp: new Date(now).toISOString(),
    shouldProtect,
    reason,
    matchedCount: matched.length,
    matchedAlerts: matched.slice(0, 10),
    holdUntil: holdUntil ? new Date(holdUntil).toISOString() : null,
    portalId: portalId || null,
    home: {
        lat: homeLat,
        lon: homeLon,
        source: hasHome ? homeSource : "missing"
    },
    control: {
        normalMinSoc: clampSocStep5(CONFIG.normalMinSoc, 20),
        stormMinSoc: clampSocStep5(CONFIG.stormMinSoc, 80)
    }
};

if (!hasHome) {
    msg.stormWatch.warning = "Home location is missing. Set CONFIG.home.lat/lon or provide Victron GPS topics.";
}

return msg;

const info = msg.stormWatch || {};
const prev = !!flow.get("stormProtectActive");
const next = !!info.shouldProtect;
const portalId = info.portalId || flow.get("portalId") || "";

function clampSocStep5(v, fallback) {
    const n = Number(v);
    const base = Number.isFinite(n) ? n : fallback;
    const clipped = Math.max(0, Math.min(100, base));
    return Math.round(clipped / 5) * 5;
}

const normalMinSoc = clampSocStep5(info.control && info.control.normalMinSoc, 20);
const stormMinSoc = clampSocStep5(info.control && info.control.stormMinSoc, 80);

function settingTopic(path) {
    return `W/${portalId}/settings/0/${path}`;
}

function settingMsg(path, value) {
    return {
        topic: settingTopic(path),
        payload: JSON.stringify({ value })
    };
}

if (!portalId) {
    node.status({ fill: "yellow", shape: "ring", text: "waiting for portalId" });
    return [null, {
        payload: {
            level: "warn",
            text: "Portal ID not known yet. Waiting for Victron telemetry topic N/<portalId>/...",
            stormWatch: info
        }
    }];
}

if (next && !prev) {
    flow.set("stormProtectActive", true);
    node.status({ fill: "red", shape: "dot", text: `protect ${stormMinSoc}%` });
    return [[
        settingMsg("Settings/CGwacs/BatteryLife/MinimumSocLimit", stormMinSoc),
        settingMsg("Settings/CGwacs/BatteryLife/ForceCharge", 1)
    ], {
        payload: {
            level: "info",
            text: `Storm protection ENABLED. MinimumSoc=${stormMinSoc}, ForceCharge=1`,
            stormWatch: info
        }
    }];
}

if (!next && prev) {
    flow.set("stormProtectActive", false);
    node.status({ fill: "green", shape: "dot", text: `normal ${normalMinSoc}%` });
    return [[
        settingMsg("Settings/CGwacs/BatteryLife/ForceCharge", 0),
        settingMsg("Settings/CGwacs/BatteryLife/MinimumSocLimit", normalMinSoc)
    ], {
        payload: {
            level: "info",
            text: `Storm protection DISABLED. ForceCharge=0, MinimumSoc=${normalMinSoc}`,
            stormWatch: info
        }
    }];
}

node.status({ fill: next ? "red" : "green", shape: "ring", text: next ? "protect active" : "normal" });
return [null, {
    payload: {
        level: "debug",
        text: next ? "No change (already in protect mode)." : "No change (normal mode).",
        stormWatch: info
    }
}];

const t = String(msg.topic || "");
const m = t.match(/^N\/([^/]+)\//);
if (m) {
    flow.set("portalId", m[1]);
}

let value = msg.payload;
if (value && typeof value === "object" && value.value !== undefined) {
    value = value.value;
}
const soc = Number(value);
if (Number.isFinite(soc)) {
    flow.set("batterySoc", soc);
}

return null;

const t = String(msg.topic || "");
const m = t.match(/^N\/([^/]+)\//);
if (m) {
    flow.set("portalId", m[1]);
}

let value = msg.payload;
if (value && typeof value === "object" && value.value !== undefined) {
    value = value.value;
}

function storeIfFinite(key, maybeNumber) {
    const n = Number(maybeNumber);
    if (Number.isFinite(n)) {
        flow.set(key, n);
        return true;
    }
    return false;
}

const topicLc = t.toLowerCase();
let updated = false;

if (topicLc.endsWith("/latitude") || topicLc.endsWith("/lat")) {
    updated = storeIfFinite("gpsLatitude", value) || updated;
}
if (topicLc.endsWith("/longitude") || topicLc.endsWith("/lon")) {
    updated = storeIfFinite("gpsLongitude", value) || updated;
}

if (value && typeof value === "object") {
    updated = storeIfFinite("gpsLatitude", value.latitude) || updated;
    updated = storeIfFinite("gpsLatitude", value.lat) || updated;
    updated = storeIfFinite("gpsLongitude", value.longitude) || updated;
    updated = storeIfFinite("gpsLongitude", value.lon) || updated;
    updated = storeIfFinite("gpsLongitude", value.lng) || updated;
}

if (updated) {
    const lat = flow.get("gpsLatitude");
    const lon = flow.get("gpsLongitude");
    node.status({ fill: "blue", shape: "dot", text: `GPS ${lat},${lon}` });
}

return null;
